import{_ as a,C as r,o as s,c as n,j as t,a as i,E as d,a6 as h}from"./chunks/framework.CCKCzdWs.js";const c="/screenshots/picker-pause.png",k=JSON.parse('{"title":"Breakpoints in the browser","description":"Set a breakpoint in VS Code or a JetBrains IDE and the next test run Piwi starts pauses there in a headed browser, before a navigation, an action, a key press or an assertion, with a bar to resume, step, pick a locator that replaces the one on that line, or record the steps that come next.","frontmatter":{"title":"Breakpoints in the browser","description":"Set a breakpoint in VS Code or a JetBrains IDE and the next test run Piwi starts pauses there in a headed browser, before a navigation, an action, a key press or an assertion, with a bar to resume, step, pick a locator that replaces the one on that line, or record the steps that come next.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/editor-breakpoints.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/editor-breakpoints.html"}],["meta",{"property":"og:title","content":"Breakpoints in the browser | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Set a breakpoint in VS Code or a JetBrains IDE and the next test run Piwi starts pauses there in a headed browser, before a navigation, an action, a key press or an assertion, with a bar to resume, step, pick a locator that replaces the one on that line, or record the steps that come next."}]]},"headers":[],"relativePath":"features/editor-breakpoints.md","filePath":"features/editor-breakpoints.md","lastUpdated":1793129242000}'),l={name:"features/editor-breakpoints.md"};function p(u,e,g,w,b,f){const o=r("Needs");return s(),n("div",null,[e[0]||(e[0]=t("h1",{id:"breakpoints-in-the-browser",tabindex:"-1"},[i("Breakpoints in the browser "),t("a",{class:"header-anchor",href:"#breakpoints-in-the-browser","aria-label":'Permalink to "Breakpoints in the browser"'},"​")],-1)),d(o,{reporter:"",fixtures:""}),e[1]||(e[1]=h('<p>A breakpoint you set with the editor&#39;s own gutter click pauses the next test run the <a href="./editors.html">editor extensions</a> start, in the browser, right before the call on its line that acts on, reads or checks the page: a navigation, a click, a key press, an assertion. Piwi&#39;s bar at the top of the page lets you look at the page, step through the calls, or pick a better locator, which lands back on that line in the editor. The stop is Playwright&#39;s own debugger (<code>context.debugger</code>) without its Inspector: Piwi&#39;s bar answers it, and no JavaScript debugger attaches.</p><h2 id="pause-a-run" tabindex="-1">Pause a run <a class="header-anchor" href="#pause-a-run" aria-label="Permalink to &quot;Pause a run&quot;">​</a></h2><ol><li>Set a line breakpoint on a line with a Playwright call, in a spec or a page object: <code>await page.getByText(&#39;Pay now&#39;).click();</code>, <code>await page.goto(&#39;/checkout&#39;);</code>, <code>await page.keyboard.press(&#39;Tab&#39;);</code> or <code>await expect(page).toHaveURL(/cart/);</code>.</li><li>Run the test from Piwi: <strong>Run this test</strong>, or any command of <a href="./editor-runs.html#run-tests">Runs from the editor</a>.</li><li>The run opens a headed browser. Before the call on your line runs, the pause bar appears with the call as Playwright names it, <code>Paused at login.spec.ts:42 · Click getByText(&#39;Pay now&#39;)</code>, and a locator call&#39;s element is highlighted.</li></ol><table tabindex="0"><thead><tr><th>Button</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Resume</strong> (<kbd>Esc</kbd>)</td><td>Runs on to the next breakpoint</td></tr><tr><td><strong>Step</strong></td><td>Pauses again before the next call that acts on, reads or checks the page, breakpoint or not</td></tr><tr><td><strong>Pick a locator</strong></td><td>Opens Piwi&#39;s <a href="/features/locator-healing.html#pick-a-replacement-locator-on-the-failing-page-local-runs">element picker</a>: pick the element, choose stable parents, confirm a ranked locator; the bar comes back after</td></tr><tr><td><strong>Record here</strong></td><td>Records what you do in the page into the editor, above the paused line: <a href="#record-from-a-pause">Record from a pause</a></td></tr><tr><td><strong>Finish</strong></td><td>Runs on without pausing again in this test</td></tr></tbody></table><figure><img src="'+c+'" alt="A shop page in the browser, paused before a click on Checkout: the button highlighted, Piwi&#39;s pause bar at the top with Resume, Step, Pick a locator, Record here and Finish"><figcaption>A run paused before the click on <strong>Checkout</strong>: the element highlighted, and Piwi&#39;s bar at the top of the page.</figcaption></figure><p>The page under the bar stays live: scroll it, open the browser&#39;s developer tools, or click through it before you resume. The test timeout stops while the test is paused, and so does the paused call&#39;s own budget (<code>actionTimeout</code>, or <code>expect.timeout</code> for an assertion on that line). A wait the test started before the stop keeps its own deadline: <code>expect.poll</code>, <code>toPass</code>, or a <code>waitForRequest</code>, <code>waitForResponse</code> or <code>waitForEvent</code> around the paused call can run out while you look and fail the test: the bar then goes away, before Playwright&#39;s failure screenshot and the <code>afterEach</code> hooks. The test&#39;s duration leaves the time paused out (a test that ended under the bar too, where Piwi can correct the runner&#39;s count), and every step keeps its clock time: the dashboard&#39;s timelines draw each stop as a <strong>Paused</strong> band, and its step statistics (slowest step, wasted time) leave it out.</p><h2 id="where-the-pick-lands" tabindex="-1">Where the pick lands <a class="header-anchor" href="#where-the-pick-lands" aria-label="Permalink to &quot;Where the pick lands&quot;">​</a></h2><p>A locator you confirm replaces the locator chain on the breakpoint&#39;s line, in the file as it stands, saved or not: <code>page.getByText(&#39;Pay now&#39;).click()</code> becomes <code>page.getByRole(&#39;button&#39;, { name: &#39;Pay now&#39; }).click()</code>, and a notification says so. When the line holds no locator, because you edited it during the pause or it takes its locator from a page object (<code>checkout.payButton().click()</code>), the locator is inserted at the cursor instead, and the notification says why.</p><p>The pick is also printed in the run&#39;s terminal (<code>[piwi] Locator picked at tests/login.spec.ts:42: getByRole(…)</code>) and recorded in the run&#39;s locator snapshots, so the <a href="/features/locator-healing.html">Locator fix</a> panel shows it as <strong>Your pick</strong> once the run uploads.</p><p>The pick reaches the editor through the address <a href="./editor-recording.html#send-from-piwi-picker">Piwi Picker sends to</a>; nothing is copied to the clipboard.</p><h2 id="record-from-a-pause" tabindex="-1">Record from a pause <a class="header-anchor" href="#record-from-a-pause" aria-label="Permalink to &quot;Record from a pause&quot;">​</a></h2><p><strong>Record here</strong> hands the paused page to the editor&#39;s <a href="./editor-recording.html">recorder</a>: the steps you take from there are written into the file on a new line above the paused statement (the first line of a statement broken over lines), on the page expression in scope there, as <strong>Record here</strong> in the editor writes them, but with no <code>page.goto</code>: the page is where the test left it, signed in and filled in as the test made it. The editor opens the file at that line and starts recording. Pause and Stop are in the recorder&#39;s bar in the page and in the editor; once you stop, the pause bar comes back, and <strong>Resume</strong> runs the rest of the test from the page as you left it, which checks that the new steps fit what follows.</p><p><code>await page.pause()</code> in a test does the same without a breakpoint: in a run Piwi starts, or any headed run with breakpoints, it shows Piwi&#39;s pause bar there in place of Playwright&#39;s Inspector, with <strong>Record here</strong> among its buttons in a run Piwi starts, and Piwi adds <code>--headed</code> to a run whose spec holds a <code>page.pause()</code> call. The <code>page.pause()</code> line stays, so the next run can record from there again; remove it when the test is done. In a run without breakpoints Piwi did not start, outside a test (a <code>beforeAll</code> or <code>afterAll</code>) and on a page of a browser the test launched itself, <code>page.pause()</code> is Playwright&#39;s own, with its Inspector; in a headless browser it returns at once. <strong>Record here</strong> records http(s) pages: on a page the test made with <code>setContent</code>, or a <code>file:</code> page, the editor says so and nothing is recorded.</p><p>The test reaches the editor through <code>PIWI_RECORD_CHANNEL</code>, the socket of <a href="./editor-run-control.html#how-it-works">the run&#39;s connection</a>; a recording not started within 30 seconds is refused, and the test goes on.</p><h2 id="the-setting" tabindex="-1">The setting <a class="header-anchor" href="#the-setting" aria-label="Permalink to &quot;The setting&quot;">​</a></h2><p>Breakpoints are on by default. Turn them off with the <code>piwi.breakpoints</code> setting in VS Code, or <strong>Pause the runs Piwi starts at the editor&#39;s breakpoints</strong> under <strong>Settings → Tools → Piwi</strong> in a JetBrains IDE, kept on your machine only.</p><h2 id="what-it-needs" tabindex="-1">What it needs <a class="header-anchor" href="#what-it-needs" aria-label="Permalink to &quot;What it needs&quot;">​</a></h2><ul><li><strong><code>@piwitests/reporter</code> 0.48.0 or later</strong>, with the <a href="/guide/capture-fixtures.html">capture fixtures</a> in your tests: the pause runs in them. With an older one, the run starts anyway and the editor warns once. A reporter of 0.59.0 or older pauses before locator actions and assertions only.</li><li><strong>A run started from Piwi.</strong> The editor passes the breakpoints under the Playwright config&#39;s folder to the run as <code>PIWI_PAUSE_AT</code> (<code>tests/login.spec.ts:42;tests/pages/checkout.page.ts:9</code>, relative to that folder), with its pairing address as <code>PIWI_EDITOR_SEND</code>, and adds <code>--headed</code> to the command unless it already has <code>--headed</code>, <code>--ui</code> or <code>--debug</code>. Set <code>PIWI_PAUSE_AT</code> yourself to <a href="/features/locator-healing.html#pause-at-a-breakpoint-local-runs">pause a run you start</a>.</li></ul><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>Headed and local only.</strong> Under CI (<code>CI</code> set to anything but empty or <code>false</code>), or under Playwright&#39;s own debugger (<code>--debug</code>, <code>--debug=cli</code>, <code>PWDEBUG</code>), the run ignores the breakpoints and says why once; so does a headless run you start yourself. One Piwi starts stops with no bar, and the editor shows its page (<a href="./editor-run-control.html#a-headless-run">A headless run</a>).</li><li><strong>Only the calls Playwright&#39;s debugger stops at pause</strong>: navigations, actions, key presses and mouse moves, assertions, <code>evaluate</code>, <code>waitForFunction</code>, screenshots and an element&#39;s reads (<code>textContent</code>, <code>inputValue</code>, <code>getAttribute</code>, <code>isVisible</code>, <code>count</code>). <code>waitForTimeout</code>, <code>waitForSelector</code>, <code>waitForURL</code>, <code>waitForEvent</code>, <code>title()</code> and <code>ariaSnapshot()</code> never do, so a breakpoint on such a line, on a helper call or on a line with no Playwright call does nothing. A breakpoint in a page object method pauses every test that calls it.</li><li><strong>A run with breakpoints stops before every call</strong> and lets those off your lines go on at once, which costs about a millisecond a call.</li><li><strong>The paused call lasts as long as you looked</strong> at the page, in Playwright&#39;s trace, its HTML report and the dashboard&#39;s steps; only the statistics leave it out.</li><li><strong>A call the test ended under runs</strong> as the bar goes away, during teardown, when the test fails under the bar or does not await the call; the call is waited for, up to two seconds, so its requests stay the test&#39;s.</li><li><strong>One Inspector switch per worker.</strong> While Playwright&#39;s own <code>page.pause()</code> runs, a stop in another context opens its Inspector too, and a context that opened one keeps it. A <code>page.pause()</code> on a browser launched through a second copy of Playwright shows neither bar nor Inspector and waits until the test&#39;s timeout.</li><li><strong>Every attempt pauses.</strong> With retries, a test pauses again on its retry, and the bar says <code>attempt 2</code>.</li><li><strong>Each worker pauses its own browser.</strong> When several tests reach a breakpoint, run <code>--workers=1</code> to pause one at a time.</li><li><strong>Record here</strong> is offered from Piwi&#39;s pause bar only, never from a debugger paused in your code.</li><li><strong>Record here</strong> records the paused page alone: a tab or a popup it opens is not recorded, as in any recording.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./editor-runs.html">Runs from the editor</a>: the commands that start a run, and how the editor follows it.</li><li><a href="./editor-run-control.html">Pause and step from the editor</a>: the same stops, answered from the editor.</li><li><a href="/features/locator-healing.html">Locator healing</a>: the picker, and the panel a pick shows in.</li><li><a href="./editors.html">Editor extensions</a>: the failures, lenses and quick fixes the editor shows from your suite.</li></ul>',22))])}const y=a(l,[["render",p]]);export{k as __pageData,y as default};
